# Golden cases for the 02g `any_attribute` XML rule, generated by the Ruby reference
# (lutaml-model #1116 @ d05b3af): `ruby -Ilib <this file> <out.json>` in that worktree.
require "json"
require "lutaml/model"
require "lutaml/model/lml"
V = Lutaml::Model::Lml
DV = V::DocumentValidator
def t(name) = {"kind"=>"builtin","name"=>name}
def at(name, type = t("hash"), extra = {}) = {"name"=>name,"type"=>type}.merge(extra)
def doc(mappings, attrs = [at("id", t("string")), at("other")])
  {"lml"=>2,"model"=>"A","register"=>"default","attributes"=>attrs,"mappings"=>mappings}
end
ANY = {"kind"=>"any_attribute","to"=>"other"}
ID = {"kind"=>"attribute","name"=>["id"],"to"=>"id"}
def xml(*rules, **extra) = doc({"xml"=>{"rules"=>rules}.merge(extra)})

cases = {
  "valid_last" => xml(ID, ANY),
  "valid_only" => xml(ANY),
  "valid_not_last" => xml(ANY, ID),
  "valid_with_json_mapping" => doc({"xml"=>{"rules"=>[ID, ANY]},"json"=>{"rules"=>[{"kind"=>"element","name"=>["id"],"to"=>"id"}]}}),
  "duplicate" => xml(ID, ANY, ANY),
  "duplicate_other_target" => doc({"xml"=>{"rules"=>[ANY, ANY.merge("to"=>"id")]}}),
  "extra_key_name" => xml(ANY.merge("name"=>["x"])),
  "extra_key_namespace" => xml(ANY.merge("namespace"=>{"mode"=>"inherit"})),
  "extra_key_cdata" => xml(ANY.merge("cdata"=>true)),
  "extra_key_render" => xml(ANY.merge("render"=>{"nil"=>true})),
  "extra_key_unknown" => xml(ANY.merge("bogus"=>1)),
  "extra_key_executable" => xml(ANY.merge("with"=>"x")),
  "missing_to" => xml({"kind"=>"any_attribute"}),
  "to_null" => xml(ANY.merge("to"=>nil)),
  "to_number" => xml(ANY.merge("to"=>5)),
  "to_array" => xml(ANY.merge("to"=>["other"])),
  "to_undeclared" => xml(ANY.merge("to"=>"nope")),
  "to_string_attr" => xml(ANY.merge("to"=>"id")),
  "to_collection_hash" => doc({"xml"=>{"rules"=>[ANY]}}, [at("other", t("hash"), "collection"=>{"min"=>0,"max"=>nil})]),
  "to_collection_false_hash" => doc({"xml"=>{"rules"=>[ANY]}}, [at("other", t("hash"), "collection"=>false)]),
  "to_model_typed" => doc({"xml"=>{"rules"=>[ANY]}}, [at("other", {"kind"=>"model","id"=>"A@default"})]),
  "to_value_typed" => doc({"xml"=>{"rules"=>[ANY]}}, [at("other", {"kind"=>"value","id"=>"V@default"})]),
  "json_mapping" => doc({"json"=>{"rules"=>[ANY]}}),
  "yaml_mapping" => doc({"yaml"=>{"rules"=>[ANY]}}),
  "toml_mapping" => doc({"toml"=>{"rules"=>[ANY]}}),
  "json_mapping_extra_key" => doc({"json"=>{"rules"=>[ANY.merge("name"=>["x"])]}}),
  "json_and_xml" => doc({"json"=>{"rules"=>[ANY]},"xml"=>{"rules"=>[ANY]}}),
  "in_sequence_compositor" => xml({"kind"=>"sequence","members"=>[ANY]}),
  "in_choice_compositor" => xml({"kind"=>"choice","members"=>[ID, ANY]}),
  "in_nested_compositor" => xml({"kind"=>"sequence","members"=>[{"kind"=>"choice","members"=>[ANY]}]}),
  "in_mapping_sequence" => doc({"xml"=>{"sequence"=>[{"kind"=>"sequence","members"=>[ANY]}]}}),
  "mapping_sequence_toplevel_any" => doc({"xml"=>{"sequence"=>[ANY]}}),
  "xml_any_next_to_compositor" => xml({"kind"=>"sequence","members"=>[ID]}, ANY),
  "rule_not_object" => xml(ANY, "x"),
  "no_attributes_dangling" => doc({"xml"=>{"rules"=>[ANY]}}, []),
  "unsupported_kind_still_refused" => xml({"kind"=>"anyAttribute","to"=>"other"}),
}
out = cases.map do |name, d|
  input = JSON.generate(d)
  exp =
    begin
      DV.validate!(JSON.parse(input), kind: :document)
      nil
    rescue V::RejectedError => e
      { "reason"=>e.reason.to_s, "location"=>e.location, "detail"=>e.detail }
    end
  { "name"=>name, "kind"=>"document", "input"=>input, "expect"=>exp }
end
File.write(ARGV[0], JSON.pretty_generate(out) + "\n")
puts out.count { |c| c["expect"] }, out.size
out.each { |c| puts "#{c['name']}: #{c['expect']&.values_at('reason','location').inspect}" }
